macro_rules! Endianity {
    () => {
        # [doc = " A trait describing the endianity of some buffer."] pub trait Endianity : Debug + Default + Clone + Copy + PartialEq + Eq { # [doc = " Return true for big endian byte order."] fn is_big_endian (self) -> bool ; # [doc = " Return true for little endian byte order."] # [inline] fn is_little_endian (self) -> bool { ! self . is_big_endian () } # [doc = " Reads an unsigned 16 bit integer from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 2`."] # [inline] fn read_u16 (self , buf : & [u8]) -> u16 { let bytes : & [u8 ; 2] = buf [.. 2] . try_into () . unwrap () ; if self . is_big_endian () { u16 :: from_be_bytes (* bytes) } else { u16 :: from_le_bytes (* bytes) } } # [doc = " Reads an unsigned 32 bit integer from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 4`."] # [inline] fn read_u32 (self , buf : & [u8]) -> u32 { let bytes : & [u8 ; 4] = buf [.. 4] . try_into () . unwrap () ; if self . is_big_endian () { u32 :: from_be_bytes (* bytes) } else { u32 :: from_le_bytes (* bytes) } } # [doc = " Reads an unsigned 64 bit integer from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 8`."] # [inline] fn read_u64 (self , buf : & [u8]) -> u64 { let bytes : & [u8 ; 8] = buf [.. 8] . try_into () . unwrap () ; if self . is_big_endian () { u64 :: from_be_bytes (* bytes) } else { u64 :: from_le_bytes (* bytes) } } # [doc = " Reads an unsigned 128 bit integer from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 16`."] # [inline] fn read_u128 (self , buf : & [u8]) -> u128 { let bytes : & [u8 ; 16] = buf [.. 16] . try_into () . unwrap () ; if self . is_big_endian () { u128 :: from_be_bytes (* bytes) } else { u128 :: from_le_bytes (* bytes) } } # [doc = " Read an unsigned n-bytes integer u64."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 1` or `buf.len() > 8`."] # [inline] fn read_uint (& mut self , buf : & [u8]) -> u64 { let mut tmp = [0 ; 8] ; if self . is_big_endian () { tmp [8 - buf . len () ..] . copy_from_slice (buf) ; } else { tmp [.. buf . len ()] . copy_from_slice (buf) ; } self . read_u64 (& tmp) } # [doc = " Reads a signed 16 bit integer from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 2`."] # [inline] fn read_i16 (self , buf : & [u8]) -> i16 { self . read_u16 (buf) as i16 } # [doc = " Reads a signed 32 bit integer from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 4`."] # [inline] fn read_i32 (self , buf : & [u8]) -> i32 { self . read_u32 (buf) as i32 } # [doc = " Reads a signed 64 bit integer from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 8`."] # [inline] fn read_i64 (self , buf : & [u8]) -> i64 { self . read_u64 (buf) as i64 } # [doc = " Reads a 32 bit floating point number from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 8`."] # [inline] fn read_f32 (self , buf : & [u8]) -> f32 { f32 :: from_bits (self . read_u32 (buf)) } # [doc = " Reads a 32 bit floating point number from `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 8`."] # [inline] fn read_f64 (self , buf : & [u8]) -> f64 { f64 :: from_bits (self . read_u64 (buf)) } # [doc = " Writes an unsigned 16 bit integer `n` to `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 2`."] # [inline] fn write_u16 (self , buf : & mut [u8] , n : u16) { let bytes = if self . is_big_endian () { n . to_be_bytes () } else { n . to_le_bytes () } ; buf [.. 2] . copy_from_slice (& bytes) ; } # [doc = " Writes an unsigned 32 bit integer `n` to `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 4`."] # [inline] fn write_u32 (self , buf : & mut [u8] , n : u32) { let bytes = if self . is_big_endian () { n . to_be_bytes () } else { n . to_le_bytes () } ; buf [.. 4] . copy_from_slice (& bytes) ; } # [doc = " Writes an unsigned 64 bit integer `n` to `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 8`."] # [inline] fn write_u64 (self , buf : & mut [u8] , n : u64) { let bytes = if self . is_big_endian () { n . to_be_bytes () } else { n . to_le_bytes () } ; buf [.. 8] . copy_from_slice (& bytes) ; } # [doc = " Writes an unsigned 128 bit integer `n` to `buf`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when `buf.len() < 16`."] # [inline] fn write_u128 (self , buf : & mut [u8] , n : u128) { let bytes = if self . is_big_endian () { n . to_be_bytes () } else { n . to_le_bytes () } ; buf [.. 16] . copy_from_slice (& bytes) ; } }
    };
}

Endianity!()